on('customer', '/faqs', async () => { shell(''); const d = await GET('/faqs'); $('#main').innerHTML = `<div class="card" style="max-width:860px;margin:auto"><h1>FAQs</h1>${(d.items || d).map(f => `<details class="glass" style="padding:10px 14px;border-radius:16px;margin:8px 0"><summary><b>${esc(f.question)}</b></summary><p>${esc(f.answer)}</p></details>`).join('')}</div>`; });
